using System.Text.Json;using TracezillaShopify.Workflows;
namespace TracezillaShopify.Shopify;
public sealed class ShopifyInventoryService(IGraphQlClient client):IInventoryTarget{private const string Query="query GetInventoryItems($first:Int!,$after:String,$locationId:ID!){productVariants(first:$first,after:$after){nodes{sku inventoryItem{id tracked inventoryLevel(locationId:$locationId){quantities(names:[\"available\"]){name quantity}}}}pageInfo{hasNextPage endCursor}}}";private const string Mutation="mutation SetInventoryQuantity($input:InventorySetQuantitiesInput!){inventorySetQuantities(input:$input){userErrors{message}}}";public async Task<IReadOnlyDictionary<string,ShopifyInventory>> ReadAtLocationAsync(string id){var result=new Dictionary<string,ShopifyInventory>();string? after=null;while(true){using var payload=await client.QueryAsync(Query,new{first=250,after,locationId=id});var connection=payload.RootElement.GetProperty("data").GetProperty("productVariants");foreach(var node in connection.GetProperty("nodes").EnumerateArray()){var sku=node.GetProperty("sku").GetString()?.Trim();if(string.IsNullOrEmpty(sku))continue;var item=node.GetProperty("inventoryItem");int? available=null;if(item.TryGetProperty("inventoryLevel",out var level)&&level.ValueKind==JsonValueKind.Object)foreach(var q in level.GetProperty("quantities").EnumerateArray())if(q.GetProperty("name").GetString()=="available")available=q.GetProperty("quantity").GetInt32();result[sku]=new(sku,item.GetProperty("id").GetString()!,item.GetProperty("tracked").GetBoolean(),available);}var page=connection.GetProperty("pageInfo");if(!page.GetProperty("hasNextPage").GetBoolean())break;after=page.GetProperty("endCursor").GetString()??throw new InvalidDataException("Shopify inventory pagination is missing a cursor.");}return result;}public async Task SetAvailableAsync(ShopifyInventory item,int quantity,string location){using var payload=await client.QueryAsync(Mutation,new{input=new{name="available",reason="correction",referenceDocumentUri=$"tracezilla://inventory-sync/{item.Sku}",quantities=new[]{new{inventoryItemId=item.InventoryItemId,locationId=location,quantity,compareQuantity=item.Available}}}});var errors=payload.RootElement.GetProperty("data").GetProperty("inventorySetQuantities").GetProperty("userErrors");if(errors.GetArrayLength()>0)throw new InvalidDataException(errors[0].GetProperty("message").GetString());}}
